import { InfoTooltipServer } from "@/core/button/info-tooltip.server";
import type { SelectOption } from "@/core/select/search-select-v2";
import { SearchSelectV2 } from "@/core/select/search-select-v2";
import { AdminOnly } from "@/core/tooltip/required";
import { CodeBlock } from "@/core/widgets/code-block";
import { InputV1, InputV1Container } from "@/core/widgets/input";
import type { JobConfig, JobConfigFieldSpecifier } from "@/data/job-config.data";
import { useAdminV2 } from "@/utils/permission/permissions.client";
import { capitalizeAll, splitLines } from "@/utils/text";
import type { Func } from "@/utils/utils.types";
import { useCallback, useMemo, useState } from "react";
import { twMerge } from "tailwind-merge";
import type { ConfigStateDataType, JobConfigChipState } from "./validation.utils";
import { JobConfigUtils } from "./validation.utils";

export type JobConfigChipProps = {
  item: JobConfig;
  selected: boolean;
  state: JobConfigChipState;
  handleToggle: Func;
  handleUpdate: Func<[string, ConfigStateDataType], void>;
  columns: string[];
  errorMap?: Record<string, boolean>;
  disabled?: boolean;
};

// const ShowDebugInfo = false;
const { getFieldSpecifier, parseCondition } = JobConfigUtils;
export const JobConfigChip = ({
  item,
  selected,
  handleToggle,
  handleUpdate,
  state,
  columns,
  errorMap = {},
  disabled,
}: JobConfigChipProps) => {
  const showOptions = selected && Object.keys(state || {}).length > 0;
  const { isVDevAdmin } = useAdminV2();
  const [showHidden, setShowHidden] = useState(false);
  const showDebugInfo = showHidden && isVDevAdmin;

  const getCommonProps = useCallback(
    (fieldConfig: JobConfigFieldSpecifier<true>, key = "unknown") => ({
      top: fieldConfig?.title || capitalizeAll(key, "_"),
      disabled: !(isVDevAdmin && showHidden) && parseCondition(fieldConfig.hidden, state, key + "-disabled"),
      hideIfDisabled: !(isVDevAdmin && showHidden),
      className: "animate-delay-5",
      // hideIfDisabled: true,
      required: parseCondition(fieldConfig.required, state, key + "-required"),
      adminOnly: parseCondition(fieldConfig.hidden, state, key + "-admin-show") ? "field" : undefined,
      fullWidth: true,
      bottom: (
        <div className="text-xs py-1 text-slate-400/75 mt-0 ml-1 max-w-xs">{splitLines(fieldConfig.description)}</div>
      ),
      after: showDebugInfo ? <InfoTooltipServer tooltip={JSON.stringify(fieldConfig, null, 2)} /> : undefined,
    }),
    [isVDevAdmin, state, showDebugInfo, showHidden]
  );

  const renderList = useMemo(
    () =>
      Object.entries(state)
        .map<[name: string, value: string | boolean, fieldSpecifier: JobConfigFieldSpecifier<true>]>(
          ([k, v]) => [k, typeof v === "boolean" ? v : `${v}`, getFieldSpecifier(item, k)] as const
        )
        .map((c) => [...c, getCommonProps(c?.[2], c?.[0])] as const)
        .filter((c) => c[3].disabled && c[3].hideIfDisabled),
    // .sort(([aKey, _, c1], [bKey, __, c2]) => {
    //   // false (0) first, true (1) last
    //   const hiddenCmp = Number(c1.hidden) - Number(c2.hidden);
    //   if (hiddenCmp !== 0) return hiddenCmp;

    //   return aKey.localeCompare(bKey);
    // }),
    [state, item]
  );

  console.log(renderList.length);

  return (
    <div className="col">
      <div
        role="button"
        className={twMerge(
          "min-w-[200px] max-w-[500px] w-[470px] hover:bg-slate-50 transition-all cursor-pointer",
          "rounded-xl px-4 py-2 bg-slate-50 relative animate-fadeInUp",
          "text-neutral border border-slate-100 h-full",
          selected && "border-neutral/50 shadow -translate-y-2 [transition-easing:cubic-bezier(0.4,0,0.2,1)]",
          disabled ? "opacity-50 cursor-not-allowed" : "hover:border-info/25"
        )}
        onClick={() => !disabled && handleToggle()}
      >
        <div className="row items-center gap-1">
          <input
            type="checkbox"
            className="checkbox checkbox-sm mr-1"
            checked={selected}
            readOnly
            disabled={disabled}
          />
          <span className="font-medium mr-1.5">{item.title}</span>
          {item.scope?.admin_only && <AdminOnly className="mr-0" name="item" />}
          {isVDevAdmin && <InfoTooltipServer delayShow={0} tooltip={JSON.stringify(state, null, 2)} />}
        </div>
        {isVDevAdmin && (
          <div className="text-slate-400/70 text-xs ml-[30px] mr-1.5 -mt-0.5 mb-1 empty:hidden">{item.dev_notes}</div>
        )}
        <div className="text-xs text-slate-400 ml-[30px] mr-2">{item.description}</div>
      </div>
      {showOptions && (
        <>
          <div className="divider divider-horizontal [&:before]:bg-neutral/25 [&:after]:bg-neutral/25 h-16 bottom-0 min-h-16 z-30 mx-auto animate-fadeInUp" />
          <div className="border shadow-lg rounded-xl h-fit card card-compact animate-fadeInUp animate-delay-2 w-fit mx-auto">
            <div className="row items-center justify-between">
              <div className="card-title">Config Options</div>
              {isVDevAdmin && (
                <InputV1
                  element="checkbox"
                  before={`${showHidden ? "Hide" : "Show"} hidden`}
                  // _className="min-w-fit h-fit border bg-slate-50 px-1"
                  labelClassName="cursor-pointer gap-0 px-0"
                  size="sm"
                  isToggle
                  onChange={(e) => setShowHidden(e.target.checked)}
                />
              )}
            </div>
            {renderList.map(([key, value, fieldConfig, commonProps]) => {
              if (["job_column", "job_column_list"].includes(fieldConfig.type) || fieldConfig?.options?.length) {
                const isSingle = fieldConfig.type === "job_column" || !!fieldConfig.single_select;
                const optionConfig = fieldConfig.option_config || {};
                const options = (fieldConfig.options || columns).map<SelectOption>((o) => ({
                  ...optionConfig?.[o],
                  label: optionConfig?.[o]?.label || o,
                  id: o,
                }));
                return (
                  <InputV1Container
                    key={key}
                    error={errorMap[key] && "Please select an option"}
                    errorClassName="mt-0 ml-1 !text-xs"
                    {...commonProps}
                  >
                    <SearchSelectV2
                      options={options}
                      value={value ? `${value}`.split(",") : []}
                      labelClassName="capitalize max-w-72"
                      customLabel={({ selected }) => (
                        <>
                          {selected.map((s, sIdx, arr) => (
                            <span key={sIdx} className={twMerge(s.className)}>
                              {s.label}
                              {sIdx < arr.length - 1 && ","}
                            </span>
                          ))}
                        </>
                      )}
                      optionClassName="capitalize break-all pr-1"
                      dropdownClassName="w-64"
                      selectClassName={twMerge("min-w-72", errorMap[key] && "border-warning/50")}
                      singleSelect={isSingle}
                      closeOnSelect={isSingle}
                      {...getCommonProps(fieldConfig, key)}
                      hideSearch={options.length < 10}
                      onChange={(value) => {
                        handleUpdate(key, value.join(","));
                      }}
                    />
                  </InputV1Container>
                );
              }

              if (fieldConfig.type === "boolean") {
                return (
                  <InputV1
                    key={key}
                    element="checkbox"
                    isToggle
                    checked={value as boolean}
                    onChange={(e) => {
                      handleUpdate(key, (e.target as HTMLInputElement).checked);
                    }}
                    {...commonProps}
                    error={errorMap[key] && "Please enter a value"}
                    errorClassName="ml-1 !text-xs"
                  />
                );
              }

              const isNumber = fieldConfig.type === "number";
              return (
                <InputV1
                  key={key}
                  value={isNumber ? Number(value) : `${value}`}
                  type={isNumber ? "number" : "text"}
                  onChange={(e) => {
                    handleUpdate(key, e.target.value);
                  }}
                  {...commonProps}
                  error={errorMap[key] && "Please enter a value"}
                  errorClassName="ml-1 !text-xs"
                />
              );
            })}
            {showDebugInfo && (
              <>
                <CodeBlock content={state} title={"state"} fullHeight className="max-w-xs max-h-[400px] mt-4 border" />
                <CodeBlock content={item} title={"item"} fullHeight className="max-w-xs max-h-[400px] mt-4 border" />
              </>
            )}
          </div>
        </>
      )}
    </div>
  );
};

