            disabled={disabled}
          />
          <span className="font-medium mr-1.5">{item.title}</span>
          {item.scope?.admin_only && <AdminOnly className="mr-0" name="item" />}
          {isVDevAdmin && <InfoTooltipServer delayShow={0} tooltip={JSON.stringify(state, null, 2)} />}
        </div>
        {isVDevAdmin && (
          <div className="text-slate-400/70 text-xs ml-[30px] mr-1.5 -mt-0.5 mb-1 empty:hidden">{item.dev_notes}</div>
        )}
        <div className="text-xs text-slate-400 ml-[30px] mr-2">{item.description}</div>
      </div>
      {showOptions && (
        <>
          <div className="divider divider-horizontal [&:before]:bg-neutral/25 [&:after]:bg-neutral/25 h-16 bottom-0 min-h-16 z-30 mx-auto animate-fadeInUp" />
          <div className="border shadow-lg rounded-xl h-fit card card-compact animate-fadeInUp animate-delay-2 w-fit mx-auto">
            <div className="row items-center justify-between">
              <div className="card-title">Config Options</div>
              {isVDevAdmin && (
                <InputV1
                  element="checkbox"
                  before={`${showHidden ? "Hide" : "Show"} hidden`}
                  // _className="min-w-fit h-fit border bg-slate-50 px-1"
                  labelClassName="cursor-pointer gap-0 px-0"
                  size="sm"
                  isToggle
                  onChange={(e) => setShowHidden(e.target.checked)}
                />
              )}
            </div>
            {visibleList.map(([key, value, fieldConfig, commonProps]) => {
              if (["job_column", "job_column_list"].includes(fieldConfig.type) || fieldConfig?.options?.length) {
                const isSingle = fieldConfig.type === "job_column" || !!fieldConfig.single_select;
                const optionConfig = fieldConfig.option_config || {};
                const options = (fieldConfig.options || columns).map<SelectOption>((o) => ({
                  ...optionConfig?.[o],
                  label: optionConfig?.[o]?.label || o,
                  id: o,
                }));
                return (
                  <InputV1Container
                    key={key}
                    error={errorMap[key] && "Please select an option"}
                    errorClassName="mt-0 ml-1 !text-xs"
                    {...commonProps}
                  >
                    <SearchSelectV2
                      options={options}
                      value={value ? `${value}`.split(",") : []}
                      labelClassName="capitalize max-w-72"
                      customLabel={({ selected }) => (
                        <>
                          {selected.map((s, sIdx, arr) => (
                            <span key={sIdx} className={twMerge(s.className)}>
                              {s.label}
                              {sIdx < arr.length - 1 && ","}
                            </span>
                          ))}
                        </>
                      )}
                      optionClassName="capitalize break-all pr-1"
                      dropdownClassName="w-64"
                      selectClassName={twMerge("min-w-72", errorMap[key] && "border-warning/50")}
                      singleSelect={isSingle}
                      closeOnSelect={isSingle}
                      {...getCommonProps(fieldConfig, key)}
                      hideSearch={options.length < 10}
                      onChange={(value) => {
                        handleUpdate(key, value.join(","));
                      }}
                    />
                  </InputV1Container>
                );
              }

              if (fieldConfig.type === "boolean") {
                return (
                  <InputV1
                    key={key}
                    element="checkbox"
                    isToggle
                    checked={value as boolean}
                    onChange={(e) => {
                      handleUpdate(key, (e.target as HTMLInputElement).checked);
                    }}
                    {...commonProps}
                    error={errorMap[key] && "Please enter a value"}
                    errorClassName="ml-1 !text-xs"
                  />
                );
              }

              const isNumber = fieldConfig.type === "number";
              return (
                <InputV1
                  key={key}
                  value={isNumber ? Number(value) : `${value}`}
                  type={isNumber ? "number" : "text"}
                  onChange={(e) => {
                    handleUpdate(key, e.target.value);
                  }}
                  {...commonProps}
                  error={errorMap[key] && "Please enter a value"}
                  errorClassName="ml-1 !text-xs"
                />
              );
            })}
            {showDebugInfo && (
              <>
                <CodeBlock content={state} title={"state"} fullHeight className="max-w-xs max-h-[400px] mt-4 border" />
                <CodeBlock content={item} title={"item"} fullHeight className="max-w-xs max-h-[400px] mt-4 border" />
              </>
            )}
          </div>
        </>
      )}
    </div>
  );
};
